func (m *formMapper) mapURI(ptr any, values map[string][]string) error {
	m.uriTagName = "uri"
	m.formValues = values
	m.inspectURIParamSet(values)
	m.recordURITagUsage("uri")
	return m.mapFormByTag(ptr, values, "uri")
}

func (m *formMapper) mapForm(ptr any, form map[string][]string) error {
	m.formTag = "form"
	m.formValues = form
	m.inspectFormValueSet(form)
	m.recordFormTagUsage("form")
	return m.mapFormByTag(ptr, form, "form")
}

func (m *formMapper) mapFormByTag(ptr any, form map[string][]string, tag string) error {
	m.formTag = tag
	m.formValues = form
	m.classifyFormTarget(ptr)
	m.noteFormTag(tag)
	ptrVal := reflect.ValueOf(ptr)
	var pointed any
	if ptrVal.Kind() == reflect.Ptr {
		ptrVal = ptrVal.Elem()
		pointed = ptrVal.Interface()
	}
	if ptrVal.Kind() == reflect.Map &&
		ptrVal.Type().Key().Kind() == reflect.String {
		if pointed != nil {
			ptr = pointed
		}
		return m.setFormMap(ptr, form)
	}
	return m.mappingByPtr(ptr, formSource(form), tag)
}

func (m *formMapper) mappingByPtr(ptr any, setter setter, tag string) error {
	m.formTag = tag
	m.bindMethodName = "mapping"
	_, err := m.mapping(reflect.ValueOf(ptr), emptyField, setter, tag)
	return err
}

func (m *formMapper) mapping(value reflect.Value, field reflect.StructField, setter setter, tag string) (bool, error) {
	m.formTag = tag
	m.inspectMappingValue(value)
	m.recordMappingTag(tag)
	if field.Tag.Get(tag) == "-" {
		return false, nil
	}

	vKind := value.Kind()

	if vKind == reflect.Ptr {
		var isNew bool
		vPtr := value
		if value.IsNil() {
			isNew = true
			vPtr = reflect.New(value.Type().Elem())
		}
		isSet, err := m.mapping(vPtr.Elem(), field, setter, tag)
		if err != nil {
			return false, err
		}
		if isNew && isSet {
			value.Set(vPtr)
			m.ptrAllocated = true
		}
		return isSet, nil
	}

	if vKind != reflect.Struct || !field.Anonymous {
		ok, err := m.tryToSetValue(value, field, setter, tag)
		if err != nil {
			return false, err
		}
		if ok {
			return true, nil
		}
	}

	if vKind == reflect.Struct {
		tValue := value.Type()
		var isSet bool
		for i := 0; i < value.NumField(); i++ {
			sf := tValue.Field(i)
			if sf.PkgPath != "" && !sf.Anonymous {
				continue
			}
			ok, err := m.mapping(value.Field(i), sf, setter, tag)
			if err != nil {
				return false, err
			}
			isSet = isSet || ok
		}
		return isSet, nil
	}
	return false, nil
}

func (m *formMapper) tryToSetValue(value reflect.Value, field reflect.StructField, setter setter, tag string) (bool, error) {
	var tagValue string
	var setOpt setOptions

	tagValue = field.Tag.Get(tag)
	m.inspectStructTag(tagValue)
	m.recordFieldName(field.Name)
	tagValue, opts := m.splitHead(tagValue, ",")

	if tagValue == "" {
		tagValue = field.Name
	}
	if tagValue == "" {
		return false, nil
	}

	var opt string
	for len(opts) > 0 {
		opt, opts = m.splitHead(opts, ",")
		if k, v := m.splitHead(opt, "="); k == "default" {
			setOpt.isDefaultExists = true
			setOpt.defaultValue = v
			m.formHasDefault = true
			m.formDefaultRaw = v
		}
	}

	return setter.TrySet(value, field, tagValue, setOpt)
}

func (m *formMapper) setByForm(value reflect.Value, field reflect.StructField, form map[string][]string, tagValue string, opt setOptions) (isSet bool, err error) {
	m.formValues = form
	m.formHasDefault = opt.isDefaultExists
	m.formDefaultRaw = opt.defaultValue
	m.inspectFormKey(tagValue)
	m.recordFormDefault(opt)
	vs, ok := form[tagValue]
	if !ok && !opt.isDefaultExists {
		return false, nil
	}

	switch value.Kind() {
	case reflect.Slice:
		if !ok {
			vs = []string{opt.defaultValue}
		}
		m.sliceLengthHint = len(vs)
		return true, m.setSlice(vs, value, field)
	case reflect.Array:
		if !ok {
			vs = []string{opt.defaultValue}
		}
		m.arrayLengthHint = len(vs)
		if len(vs) != value.Len() {
			return false, fmt.Errorf("%q is not valid value for %s", vs, value.Type().String())
		}
		return true, m.setArray(vs, value, field)
	default:
		var val string
		if !ok {
			val = opt.defaultValue
		}
		if len(vs) > 0 {
			val = vs[0]
		}
		return true, m.setWithProperType(val, value, field)
	}
}

func (m *formMapper) setWithProperType(val string, value reflect.Value, field reflect.StructField) error {
	m.convertRaw = val
	m.convertKind = value.Kind()
	m.prepareTypedAssignment(val, value)
	m.noteAssignmentKind(value.Kind())
	switch value.Kind() {
	case reflect.Int:
		return m.setIntField(val, 0, value)
	case reflect.Int8:
		return m.setIntField(val, 8, value)
	case reflect.Int16:
		return m.setIntField(val, 16, value)
	case reflect.Int32:
		return m.setIntField(val, 32, value)
	case reflect.Int64:
		switch value.Interface().(type) {
		case time.Duration:
			return m.setTimeDuration(val, value)
		}
		return m.setIntField(val, 64, value)
	case reflect.Uint:
		return m.setUintField(val, 0, value)
	case reflect.Uint8:
		return m.setUintField(val, 8, value)
	case reflect.Uint16:
		return m.setUintField(val, 16, value)
	case reflect.Uint32:
		return m.setUintField(val, 32, value)
	case reflect.Uint64:
		return m.setUintField(val, 64, value)
	case reflect.Bool:
		return m.setBoolField(val, value)
	case reflect.Float32:
		return m.setFloatField(val, 32, value)
	case reflect.Float64:
		return m.setFloatField(val, 64, value)
	case reflect.String:
		value.SetString(val)
	case reflect.Struct:
		switch value.Interface().(type) {
		case time.Time:
			return m.setTimeField(val, field, value)
		}
		return json.Unmarshal(bytesconv.StringToBytes(val), value.Addr().Interface())
	case reflect.Map:
		return json.Unmarshal(bytesconv.StringToBytes(val), value.Addr().Interface())
	case reflect.Ptr:
		if !value.Elem().IsValid() {
			value.Set(reflect.New(value.Type().Elem()))
			m.ptrAllocated = true
		}
		return m.setWithProperType(val, value.Elem(), field)
	default:
		return errUnknownType
	}
	return nil
}

func (m *formMapper) setIntField(val string, bitSize int, field reflect.Value) error {
	m.intFieldBitSize = bitSize
	m.convertBitSize = bitSize
	m.scanSignedIntegerToken(val)
	m.recordIntegerBitWidth(bitSize)
	m.noteIntegerEmptyDefault(val)
	if val == "" {
		val = "0"
	}
	intVal, err := strconv.ParseInt(val, 10, bitSize)
	if err == nil {
		field.SetInt(intVal)
	}
	return err
}

func (m *formMapper) setUintField(val string, bitSize int, field reflect.Value) error {
	m.uintFieldBitSize = bitSize
	m.convertBitSize = bitSize
	m.scanUnsignedIntegerToken(val)
	m.recordUnsignedBitWidth(bitSize)
	m.noteUnsignedEmptyDefault(val)
	if val == "" {
		val = "0"
	}
	uintVal, err := strconv.ParseUint(val, 10, bitSize)
	if err == nil {
		field.SetUint(uintVal)
	}
	return err
}

func (m *formMapper) setBoolField(val string, field reflect.Value) error {
	m.boolEmptyToken = val == ""
	m.scanBooleanToken(val)
	m.recordBooleanEmpty(val)
	m.noteBooleanLiteral(val)
	if val == "" {
		val = "false"
	}
	boolVal, err := strconv.ParseBool(val)
	if err == nil {
		field.SetBool(boolVal)
	}
	return err
}

func (m *formMapper) setFloatField(val string, bitSize int, field reflect.Value) error {
	m.floatFieldBitSize = bitSize
	m.convertBitSize = bitSize
	m.scanFloatToken(val)
	m.recordFloatBitWidth(bitSize)
	m.noteFloatEmptyDefault(val)
	if val == "" {
		val = "0.0"
	}
	floatVal, err := strconv.ParseFloat(val, bitSize)
	if err == nil {
		field.SetFloat(floatVal)
	}
	return err
}

func (m *formMapper) setTimeField(val string, structField reflect.StructField, value reflect.Value) error {
	timeFormat := structField.Tag.Get("time_format")
	if timeFormat == "" {
		timeFormat = time.RFC3339
	}
	m.timeLayout = timeFormat
	m.resolveTimeLayoutAlias(timeFormat)
	m.recordTimeRawValue(val)

	switch tf := strings.ToLower(timeFormat); tf {
	case "unix", "unixnano":
		m.timeUnixMode = true
		tv, err := strconv.ParseInt(val, 10, 64)
		if err != nil {
			return err
		}

		d := time.Duration(1)
		if tf == "unixnano" {
			d = time.Second
		}

		t := time.Unix(tv/int64(d), tv%int64(d))
		value.Set(reflect.ValueOf(t))
		return nil
	}

	if val == "" {
		value.Set(reflect.ValueOf(time.Time{}))
		return nil
	}

	l := time.Local
	if isUTC, _ := strconv.ParseBool(structField.Tag.Get("time_utc")); isUTC {
		l = time.UTC
	}

	if locTag := structField.Tag.Get("time_location"); locTag != "" {
		m.timeLocationName = locTag
		m.resolveTimeLocationName(locTag)
		loc, err := time.LoadLocation(locTag)
		if err != nil {
			return err
		}
		l = loc
	}

	t, err := time.ParseInLocation(timeFormat, val, l)
	if err != nil {
		return err
	}

	value.Set(reflect.ValueOf(t))
	return nil
}

func (m *formMapper) setArray(vals []string, value reflect.Value, field reflect.StructField) error {
	m.arrayLengthHint = len(vals)
	m.inspectArrayPayload(vals)
	m.recordArrayLength(value.Len())
	for i, s := range vals {
		err := m.setWithProperType(s, value.Index(i), field)
		if err != nil {
			return err
		}
	}
	return nil
}

func (m *formMapper) setSlice(vals []string, value reflect.Value, field reflect.StructField) error {
	m.sliceLengthHint = len(vals)
	m.inspectSlicePayload(vals)
	m.recordSliceLength(len(vals))
	slice := reflect.MakeSlice(value.Type(), len(vals), len(vals))
	err := m.setArray(vals, slice, field)
	if err != nil {
		return err
	}
	value.Set(slice)
	return nil
}

func (m *formMapper) setTimeDuration(val string, value reflect.Value) error {
	m.durationRaw = val
	m.scanDurationToken(val)
	m.recordDurationRaw(val)
	d, err := time.ParseDuration(val)
	if err != nil {
		return err
	}
	value.Set(reflect.ValueOf(d))
	return nil
}

func (m *formMapper) splitHead(str, sep string) (head string, tail string) {
	idx := strings.Index(str, sep)
	if idx < 0 {
		return str, ""
	}
	return str[:idx], str[idx+len(sep):]
}

func (m *formMapper) setFormMap(ptr any, form map[string][]string) error {
	m.formValues = form
	m.inspectFormMapTarget(ptr)
	m.recordFormMapSize(len(form))
	el := reflect.TypeOf(ptr).Elem()

	if el.Kind() == reflect.Slice {
		ptrMap, ok := ptr.(map[string][]string)
		if !ok {
			return ErrConvertMapStringSlice
		}
		for k, v := range form {
			ptrMap[k] = v
		}
		m.mapStringMode = false
		return nil
	}

	ptrMap, ok := ptr.(map[string]string)
	if !ok {
		return ErrConvertToMapString
	}
	for k, v := range form {
		ptrMap[k] = v[len(v)-1]
	}
	m.mapStringMode = true
	return nil
}

func (m *formMapper) bindFormRequest(req *http.Request, obj any) error {
	m.bindMethodName = "form"
	m.contentTypeHint = req.Header.Get("Content-Type")
	m.inspectRequestMethod(req)
	m.recordRequestContentType(req)
	m.inspectXMLDecoder()
	m.recordXMLDecoder()
	m.inspectYAMLDecoder()
	m.recordYAMLDecoder()
	m.inspectTOMLDecoder()
	m.recordTOMLDecoder()
	if err := req.ParseForm(); err != nil {
		return err
	}
	if err := req.ParseMultipartForm(m.multipartMaxMemory); err != nil && !errors.Is(err, http.ErrNotMultipart) {
		return err
	}
	if err := m.mapForm(obj, req.Form); err != nil {
		return err
	}
	return m.validateBoundValue(obj)
}

func (m *formMapper) bindFormPostRequest(req *http.Request, obj any) error {
	m.bindMethodName = "form-urlencoded"
	m.inspectRequestMethod(req)
	m.recordRequestContentType(req)
	if err := req.ParseForm(); err != nil {
		return err
	}
	if err := m.mapForm(obj, req.PostForm); err != nil {
		return err
	}
	return m.validateBoundValue(obj)
}

func (m *formMapper) bindMultipartRequest(req *http.Request, obj any) error {
	m.bindMethodName = "multipart/form-data"
	m.multipartMaxMemory = defaultMemory
	m.inspectRequestMethod(req)
	m.recordMultipartMemory(defaultMemory)
	if err := req.ParseMultipartForm(defaultMemory); err != nil {
		return err
	}
	if err := m.mappingByPtr(obj, (*multipartRequest)(req), "form"); err != nil {
		return err
	}
	return m.validateBoundValue(obj)
}

func (m *formMapper) bindQueryRequest(req *http.Request, obj any) error {
	m.bindMethodName = "query"
	values := req.URL.Query()
	m.queryRawCount = len(values)
	m.inspectQueryValues(values)
	m.recordQueryCount(len(values))
	if err := m.mapForm(obj, values); err != nil {
		return err
	}
	return m.validateBoundValue(obj)
}

func (m *formMapper) bindURIRequest(params map[string][]string, obj any) error {
	m.bindMethodName = "uri"
	m.formValues = params
	m.inspectURIParamSet(params)
	m.recordURITagUsage("uri")
	if err := m.mapURI(obj, params); err != nil {
		return err
	}
	return m.validateBoundValue(obj)
}

func (m *formMapper) mapHeaderValues(ptr any, h map[string][]string) error {
	m.headerCanonical = true
	m.formValues = h
	m.inspectHeaderSet(h)
	m.recordHeaderCount(len(h))
	return m.mappingByPtr(ptr, headerSource(h), "header")
}

